mapper.update:
UPDATE t_platform_txn
SET matched_amount = #{matchedAmount}, actual_fee = #{actualFee}, settled_amount = #{settledAmount}, status = #{status}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version}

UPDATE t_platform_txn t
JOIN (VALUES
ROW(#{c.record.id}, #{c.record.version}, #{c.matchedAmount}, #{c.actualFee}, #{c.settledAmount}, #{c.status})
) AS v (id, version, matched_amount, actual_fee, settled_amount, status)
  ON t.id = v.id AND t.version = v.version
SET t.matched_amount = v.matched_amount, t.actual_fee = v.actual_fee, t.settled_amount = v.settled_amount, t.status = v.status, t.version = t.version + 1, t.update_time = #{now}
WHERE t.id IN #{c.record.id}
